class wf_instanciaActions extends sfActions
{
  public function executeIndex()
  {
    //return $this->forward('wf_instancia', 'list');
  }

  public function executeList()
  {
    $this->wf_instancias = WfInstanciaPeer::doSelect(new Criteria());
  }

  public function executeShow()
  {
    $this->wf_instancia = WfInstanciaPeer::retrieveByPk($this->getRequestParameter('wfinstancia_id'));
    $this->forward404Unless($this->wf_instancia);
  }

  public function executeCreate()
  {
    $this->wf_instancia = new WfInstancia();

    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
    $this->wf_instancia = WfInstanciaPeer::retrieveByPk($this->getRequestParameter('wfinstancia_id'));
    $this->forward404Unless($this->wf_instancia);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('wfinstancia_id'))
    {
      $wf_instancia = new WfInstancia();
    }
    else
    {
      $wf_instancia = WfInstanciaPeer::retrieveByPk($this->getRequestParameter('wfinstancia_id'));
      $this->forward404Unless($wf_instancia);
    }

   // $wf_instancia->setWfinstanciaId($this->getRequestParameter('wfinstancia_id'));
    $wf_instancia->setUsuarioId($this->getRequestParameter('usuario_id') ? $this->getRequestParameter('usuario_id') : null);
    $wf_instancia->setWfActividadId($this->getRequestParameter('wf_actividad_id') ? $this->getRequestParameter('wf_actividad_id') : null);
    $wf_instancia->setCominternaId($this->getRequestParameter('cominterna_id') ? $this->getRequestParameter('cominterna_id') : null);
    $wf_instancia->setComrecibidaId($this->getRequestParameter('comrecibida_id') ? $this->getRequestParameter('comrecibida_id') : null);
    $wf_instancia->setWfFlujoId($this->getRequestParameter('wf_flujo_id') ? $this->getRequestParameter('wf_flujo_id') : null);
    $wf_instancia->setEstaAbierta($this->getRequestParameter('esta_abierta', 0));
    if ($this->getRequestParameter('fecha_i'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_i'), $this->getUser()->getCulture());
      $wf_instancia->setFechaI("$y-$m-$d");
    }
    if ($this->getRequestParameter('fecha_f'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_f'), $this->getUser()->getCulture());
      $wf_instancia->setFechaF("$y-$m-$d");
    }
    if ($this->getRequestParameter('fecha_ultima_actividad'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_ultima_actividad'), $this->getUser()->getCulture());
      $wf_instancia->setFechaUltimaActividad("$y-$m-$d");
    }
    $wf_instancia->setObservaciones($this->getRequestParameter('observaciones'));

    $wf_instancia->save();

    return $this->redirect($this->getRequest()->getScriptName().'/wf_instancia/show?wfinstancia_id='.$wf_instancia->getWfinstanciaId());
  }

  public function executeDelete()
  {
    $wf_instancia = WfInstanciaPeer::retrieveByPk($this->getRequestParameter('wfinstancia_id'));

    $this->forward404Unless($wf_instancia);

    $wf_instancia->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/wf_instancia/list');
  }
}
